# The top result matches the title and artists exactly, so we can use the first result's song_id for this song.
# Let's automate this for all songs in old_songs, collecting their song_ids if found.
old_song_ids = []
for song in old_songs:
    query = f'{song["title"]} {song["artist"]}'
    results = apis.spotify.search_songs(access_token=spotify_access_token, query=query, page_limit=5)
    # Find the best match: exact title and all artists present
    found_id = None
    for result in results:
        if result["title"].lower() == song["title"].lower():
            result_artists = set(a["name"].lower() for a in result["artists"])
            song_artists = set(a.strip().lower() for a in song["artist"].split(","))
            if song_artists.issubset(result_artists):
                found_id = result["song_id"]
                break
    if found_id:
        old_song_ids.append(found_id)
    else:
        old_song_ids.append(None)  # Mark as not found

print(old_song_ids)

