steps.code:
# The search returns the correct song as the first result (title and artists match exactly).
# Let's automate this for all old songs: for each, search and pick the top result with an exact title match (case-insensitive).
# We'll build a mapping from (title, artist) to song_id for all old songs.

def find_song_id(song, access_token):
    query = f'{song["title"]} {song["artist"]}'
    results = apis.spotify.search_songs(access_token=access_token, query=query, page_limit=5)
    # Find the first result with exact title match (case-insensitive)
    for result in results:
        if result["title"].strip().lower() == song["title"].strip().lower():
            return result["song_id"]
    return None

old_song_id_map = {}
for song in old_songs:
    song_id = find_song_id(song, spotify_access_token)
    old_song_id_map[(song["title"], song["artist"])] = song_id

print(old_song_id_map)

