# Now, let's remove all old songs from all playlists where they currently appear.
# Assume we have:
# - old_song_to_spotify_id: dict mapping (title, artist) to song_id
# - playlists_with_old_songs: dict mapping playlist_id to list of song_ids to remove

# For this step, let's define the variables as they would be from previous steps (for context):
# old_song_to_spotify_id = {("On the Border of Reality", "Lily Moon, Zoey James"): 123, ...}
# playlists_with_old_songs = {playlist_id1: [song_id1, song_id2], playlist_id2: [song_id3], ...}

# Let's remove each old song from each playlist where it appears.
removal_results = []
for playlist_id, song_ids in playlists_with_old_songs.items():
    for song_id in song_ids:
        result = apis.spotify.remove_song_from_playlist(
            playlist_id=playlist_id,
            song_id=song_id,
            access_token=spotify_access_token
        )
        removal_results.append({
            "playlist_id": playlist_id,
            "song_id": song_id,
            "result": result
        })
print(removal_results)

