steps.code:
# Let's extract the best match (exact title and artist set) for each old song from the search_results.
# We'll build old_song_to_spotify_id as a list of dicts: {"title", "artist", "song_id"}.

def normalize_artists(artist_str):
    # Split by comma, strip whitespace, lowercase
    return set(a.strip().lower() for a in artist_str.split(","))

old_song_to_spotify_id = []
for entry in search_results:
    title = entry["title"]
    artist_str = entry["artist"]
    target_artists = normalize_artists(artist_str)
    found_id = None
    for song in entry["results"]:
        # Match title (case-insensitive, strip) and artist set
        if song["title"].strip().lower() == title.strip().lower():
            song_artists = set(a["name"].strip().lower() for a in song["artists"])
            if song_artists == target_artists:
                found_id = song["song_id"]
                break
    old_song_to_spotify_id.append({
        "title": title,
        "artist": artist_str,
        "song_id": found_id
    })

print(old_song_to_spotify_id)

