steps.code:
# I will fetch the metadata for all unique_song_ids using the show_song API.
# To avoid hitting any rate limits, I'll fetch them in batches of 10.

song_metadata = {}
for i in range(0, len(unique_song_ids), 10):
    batch = unique_song_ids[i:i+10]
    for song_id in batch:
        song_info = apis.spotify.show_song(song_id=song_id)
        if song_info and "song_id" in song_info:
            song_metadata[song_id] = song_info

print(song_metadata)

