# Now let's fetch details for all unique song_ids using the show_song API.
# We'll do this for all song_ids and store the mapping from song_id to (title, artists).
# To avoid flooding the output, let's fetch and print details for the first 10 song_ids as a sample.

song_id_to_details = {}
for song_id in unique_song_ids[:10]:
    detail = apis.spotify.show_song(access_token=spotify_access_token, song_id=song_id)
    song_id_to_details[song_id] = {
        "title": detail["title"],
        "artists": [artist["name"] for artist in detail["artists"]]
    }
print(song_id_to_details)

