steps.code:
# Now let's retrieve details for all unique song_ids.
# We'll fetch details for all song_ids and store them in a list.
# To avoid hitting any rate limits, let's process them in batches of 10 and print progress.

song_id_to_details = {}
for i in range(0, len(unique_song_ids), 10):
    batch = unique_song_ids[i:i+10]
    for song_id in batch:
        detail = apis.spotify.show_song(access_token=spotify_access_token, song_id=song_id)
        song_id_to_details[song_id] = detail
print(list(song_id_to_details.values())[:5])  # Show first 5 song details as a check

