# The first result matches the song title and artist exactly. Its release_date is "2021-03-23T13:53:26".
# Let's extract the release month and year (03/2021) for this song.
# Now, let's repeat this process for the rest of the songs in the TODO list.
# We'll collect the release month (MM/YYYY) for each song.

from datetime import datetime

def extract_month_year(dt_str):
    dt = datetime.fromisoformat(dt_str)
    return dt.strftime("%m/%Y")

release_months = []

for song in search_todo_songs:
    query = f'{song["title"]} {" ".join(song["artists"])}'
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the best match: exact title and all artists match
    best = None
    for r in results:
        if r["title"].lower() == song["title"].lower():
            result_artists = set(a["name"].lower() for a in r["artists"])
            song_artists = set(a.lower() for a in song["artists"])
            if song_artists.issubset(result_artists):
                best = r
                break
    if best and "release_date" in best:
        release_months.append(extract_month_year(best["release_date"]))
    else:
        release_months.append(None)

print(release_months)

